readonly struct RedisKey(string db, string id)
{
    public string Db { get; } = db;
    public string Id { get; } = id;
    public override string ToString() => $"{Db}:{Id}";
}

sealed class RedisGateway
{
    public RedisGateway(Uri endpoint) => Endpoint = endpoint;
    public Uri Endpoint { get; }
    public void Ping() { /* I/O */ }
}

struct MutableBox { public int Value; }

class Container
{
    public MutableBox Box { get; set; }
}

var c = new Container { Box = new MutableBox { Value = 1 } };
c.Box.Value = 99; // compiles but Value is still 1!
// getter returns a COPY; setter never runs
